do -- 04_sim.lua
------------------------------------------------------------------ 04_sim: deterministic territory simulation (no engine calls; runs headless in tools/simtest.py)
local D = G.D
local SIM = {}
G.SIM = SIM
local floor, ceil, min, max, abs, sqrt = math.floor, math.ceil, math.min, math.max, math.abs, math.sqrt
local function hsh(i) local s = math.sin(i * 12.9898 + 78.233) * 43758.5453; return s - floor(s) end
local function inlist(t, v) if not t then return false end for _, x in ipairs(t) do if x == v then return true end end return false end
SIM.inlist = inlist

-- grid lookup: returns '.', ',' or region index
function SIM.cell(S, x, z)
    local M = S.M
    local col = floor((-x - M.e0) / M.cell)
    local row = floor((z - M.n0) / M.cell)
    if col < 0 or row < 0 or col >= M.gw or row >= M.gh then return 0 end
    local b = M.grid:byte(row * M.gw + col + 1)
    if b == 46 then return 0 elseif b == 44 then return -1 end
    return b - 47
end

local function fac_new(f, ai, pers)
    local F = { f = f, ai = ai, pers = pers, alive = true, prodmul = 1, speedmul = 1, defmul = 1, cdmul = 1, march_t = 0, cd = {}, think = 0,
        sent = 0, captured = 0, lost = 0, mines = 0, nreg = 0, troops = 0, rb = 1 }
    return F
end

-- level starts may be compass words ("W", "NE", ...) or "+" (a neighbour of the previous start): resolved once per level.
local DIRS = { N = { 0, 1 }, S = { 0, -1 }, E = { 1, 0 }, W = { -1, 0 }, NE = { .7, .7 }, NW = { -.7, .7 }, SE = { .7, -.7 }, SW = { -.7, -.7 }, C = { 0, 0 } }
function SIM.resolve_starts(L, M)
    local R = M.regions
    local cx, cz, n = 0, 0, #R
    for _, r in ipairs(R) do cx = cx - r.x / n; cz = cz + r.z / n end      -- east = -x
    local taken = {}
    local function far_ok(i)
        for j in pairs(taken) do
            if j == i then return false end
            for _, k in ipairs(R[j].nb) do if k == i then return false end end
        end
        return true
    end
    local function pick(d, prev)
        if type(d) == "number" then taken[d] = true; return d end
        local best, bi = -1e9, nil
        if d == "+" then
            for _, k in ipairs(R[prev].nb) do
                if not taken[k] and (R[k].area > (best or 0)) then best, bi = R[k].area, k end
            end
        else
            local v = DIRS[d]
            for i, r in ipairs(R) do
                if far_ok(i) then
                    local e, z = -r.x - cx, r.z - cz
                    local sc = (d == "C") and -(e * e + z * z) or (e * v[1] + z * v[2])
                    if sc > best then best, bi = sc, i end
                end
            end
        end
        bi = bi or 1; taken[bi] = true; return bi
    end
    local function res(list)
        local out, prev = {}, nil
        for _, d in ipairs(list) do prev = pick(d, prev); out[#out + 1] = prev end
        return out
    end
    L.p = res(L.p)
    for _, a in ipairs(L.ai) do a[3] = res(a[3]) end
    L.resolved = true
end

function SIM.new(li, sv, opt)
    opt = opt or {}
    local L = D.LEVELS[li]
    local M = BB_MAPS[L.map]
    local MI = D.MAPINFO[L.map] or M.info
    if not L.resolved then SIM.resolve_starts(L, M) end
    local S = { li = li, L = L, M = M, MI = MI, t = 0, R = {}, P = {}, ST = {}, ev = {}, F = {}, fx = { drops = {}, frost = {}, shells = {} },
        over = false, win = nil, pid = 0, sv = sv, stat = { sent = 0, cap = 0, lost = 0, clash = 0, peak = 0 }, tut = L.tut and not opt.demo, demo = opt.demo }
    -- effective difficulty = level tuning (HARD) scaled by the chosen mode and the retry boost
    local base = L.diff
    local MD = (not opt.demo) and D.MODES[opt.mode or 2] or D.MODES[3]
    local fails = opt.demo and 0 or math.min(D.RETRY.max, opt.boost or 0)
    S.mode, S.boost = MD.name, fails
    local diff = {}
    for k, v in pairs(base) do diff[k] = v end
    diff.aiprod = (base.aiprod or 1) * MD.aiprod * (1 - D.RETRY.aiprod * fails)
    diff.ivm = (base.ivm or 1) * MD.ivm
    diff.delay = (base.delay or 0) + MD.delay
    diff.ng = (base.ng or 1) * MD.ng
    diff.aicd = (base.aicd or 1) * MD.aicd
    -- per-level easing used only on Relaxed/Normal (L.soft): bosses and stalemate-prone maps get extra slack
    local soft = (not opt.demo) and (opt.mode or 2) <= 2 and L.soft or nil
    if soft then
        diff.aiprod = diff.aiprod * (soft.aiprod or 1)
        diff.ivm = diff.ivm * (soft.ivm or 1)
        diff.delay = diff.delay + (soft.delay or 0)
        diff.aicd = diff.aicd * (soft.aicd or 1)
    end
    local aistart_mul = soft and soft.aistart or 1
    local pstart = MD.pstart * (1 + D.RETRY.troops * fails)
    -- factions
    S.F[1] = fac_new(1, opt.demo and "steady" or nil)
    for _, a in ipairs(L.ai) do S.F[a[1]] = fac_new(a[1], a[2]) end
    for f = 1, 5 do if not S.F[f] then S.F[f] = fac_new(f); S.F[f].alive = false; S.F[f].absent = true end end
    local up = (sv and sv.up) or {}
    local P1 = S.F[1]
    if not opt.demo then
        P1.prodmul = 1 + 0.06 * (up.recruit or 0)
        P1.speedmul = 1 + 0.06 * (up.boots or 0)
        P1.defmul = 1 + 0.08 * (up.bastion or 0)
        P1.cdbase = 1 - 0.08 * (up.quarter or 0)
    end
    S.spd = diff.spd or 1; S.reachmul = diff.reach or 1
    for f = 2, 5 do local F = S.F[f]; if F.ai then F.prodmul = diff.aiprod; F.ivm = diff.ivm; F.cdbase = diff.aicd or 1 end end
    P1.cdbase = P1.cdbase or 1
    if opt.demo then P1.ivm = 1; P1.prodmul = diff.aiprod end
    -- regions
    local starts = {}
    for _, i in ipairs(L.p) do starts[i] = 1 end
    for _, a in ipairs(L.ai) do for _, i in ipairs(a[3]) do starts[i] = a[1] end end
    for i, src in ipairs(M.regions) do
        local size = src.area < 30 and 1 or (src.area < 70 and 2 or 3)
        local ty = "town"
        if starts[i] then ty = "capital" end
        if not starts[i] then
            if inlist(MI.mines, i) then ty = "mine" elseif inlist(MI.ports, i) then ty = "port" elseif inlist(MI.forts, i) then ty = "fort" end
        end
        -- only the first start region of each faction is a capital; extra start regions are forts
        local T = D.TYPES[ty]
        local r = { i = i, name = src.name, x = src.x, z = src.z, h = src.h, hill = src.hill, coast = src.coast, area = src.area, nb = src.nb,
            size = size, ty = ty, port = inlist(MI.ports, i), owner = 0, n = 0, frozen = 0, hit = -99, active = true, flash = 0 }
        r.cap = floor(D.CAP[size] * T.cap + 0.5)
        r.prod = D.PROD * D.SIZEMUL[size] * T.prod
        r.def = T.def
        if L.active and not inlist(L.active, i) then r.active = false end
        if starts[i] then
            r.owner = starts[i]
            r.n = (r.owner == 1) and floor(((L.start or 20) + (opt.demo and 0 or 3 * (up.veteran or 0))) * pstart + 0.5) or floor((L.aistart or 20) * aistart_mul + 0.5)
        else
            local base = D.NEUTRAL[size] * (diff.ng or 1) * (0.8 + 0.45 * hsh(i * 7 + li))
            if ty == "fort" then base = base * 1.3 elseif ty == "mine" then base = base + 4 elseif ty == "port" then base = base + 1 end
            r.n = floor(base + 0.5)
            r.n0 = r.n   -- neutral garrisons regrow back to this
        end
        S.R[i] = r
    end
    -- extra start regions beyond the first become forts (one capital per faction)
    local seen = {}
    for _, i in ipairs(L.p) do if seen[1] then S.R[i].ty = "fort" end; seen[1] = true end
    for _, a in ipairs(L.ai) do
        for k, i in ipairs(a[3]) do if k > 1 then local r = S.R[i]; r.ty = "fort"; local T = D.TYPES.fort; r.cap = floor(D.CAP[r.size] * T.cap + 0.5); r.prod = D.PROD * D.SIZEMUL[r.size] * T.prod; r.def = T.def end end
    end
    for f = 1, 5 do
        local F = S.F[f]
        for k = 1, #D.ABIL do F.cd[k] = D.ABIL[k].cd * 0.6 end
    end
    S.ai_delay = diff.delay or 0
    SIM.recount(S)
    return S
end

function SIM.recount(S)
    local tot = 0
    for f = 1, 5 do local F = S.F[f]; F.nreg, F.mines, F.troops = 0, 0, 0 end
    for _, r in ipairs(S.R) do
        if r.active then
            tot = tot + 1
            if r.owner > 0 then local F = S.F[r.owner]; F.nreg = F.nreg + 1; F.troops = F.troops + r.n; if r.ty == "mine" then F.mines = F.mines + 1 end end
        end
    end
    for _, p in ipairs(S.P) do local F = S.F[p.f]; F.troops = F.troops + p.k end
    for _, s in ipairs(S.ST) do local F = S.F[s.f]; F.troops = F.troops + s.left end
    S.nact = tot
    for f = 1, 5 do
        local F = S.F[f]
        local share = F.nreg / max(1, tot)
        F.rb = (F.nreg > 0 and share < 0.3) and (1 + 0.25 * (0.3 - share) / 0.3) or 1
        F.cdmul = (F.cdbase or 1) / (1 + 0.15 * F.mines)
    end
end

function SIM.def(S, r) return r.def * (r.owner > 0 and S.F[r.owner].defmul or 1) end
function SIM.abil_ready(S, f, k) local a = D.ABIL[k]; return S.L and (f ~= 1 or S.li >= a.unlock or S.demo) and S.F[f].cd[k] <= 0 end
function SIM.abil_frac(S, f, k) local a = D.ABIL[k]; return 1 - S.F[f].cd[k] / (a.cd * S.F[f].cdmul) end
function SIM.abil_unlocked(S, k) return S.li >= D.ABIL[k].unlock end

local function ev(S, e) S.ev[#S.ev + 1] = e; if #S.ev > 400 then table.remove(S.ev, 1) end end
SIM.ev = ev

-- send a fraction of troops from each source region to dst. returns number of troops sent
function SIM.send(S, f, srcs, dst, ratio, amounts)
    local d = S.R[dst]
    if not d or not d.active or S.over then return 0 end
    local tot = 0
    for j, i in ipairs(srcs) do
        local r = S.R[i]
        if r and i ~= dst and r.owner == f and r.active and r.frozen <= 0 then
            local amt = amounts and min(floor(amounts[j]), floor(r.n)) or floor(r.n * (ratio or 1))
            if amt >= 1 then
                r.n = r.n - amt
                local k = max(1, ceil(amt / D.PACK))
                local dx, dz = d.x - r.x, d.z - r.z
                local dl = max(0.01, sqrt(dx * dx + dz * dz))
                S.ST[#S.ST + 1] = { src = i, dst = dst, f = f, left = amt, k = k, acc = 1, n = 0, ux = dx / dl, uz = dz / dl, dl = dl, port = r.port }
                tot = tot + amt
                ev(S, { k = "send", r = i, d = dst, f = f, n = amt })
            end
        end
    end
    if tot > 0 then local F = S.F[f]; F.sent = F.sent + tot; if f == 1 then S.stat.sent = S.stat.sent + tot end end
    return tot
end

local LANE = { 0, -1, 1 }
local function emit(S, s)
    local r = S.R[s.src]
    s.n = s.n + 1
    local k = min(s.k, s.left)
    s.left = s.left - k
    local lane = LANE[(s.n - 1) % 3 + 1] * 0.2
    local px, pz = -s.uz, s.ux
    S.pid = S.pid + 1
    local sx, sz = r.x + s.ux * 0.55 + px * lane, r.z + s.uz * 0.55 + pz * lane
    local d = S.R[s.dst]
    S.P[#S.P + 1] = { id = S.pid, f = s.f, k = k, x = sx, z = sz, ox = sx, oz = sz, tx = d.x + px * lane, tz = d.z + pz * lane, dst = s.dst, src = s.src,
        port = s.port, bearer = (s.n % 8 == 1), lane = lane, age = 0, sea = false }
end

local function arrive(S, p)
    local r = S.R[p.dst]
    if r.owner == p.f then
        r.n = r.n + p.k
        return
    end
    local df = SIM.def(S, r)
    r.n = r.n - p.k / df
    r.hit = S.t
    if r.n < 0 then
        local old = r.owner
        r.n = (-r.n) * df
        r.owner = p.f
        r.frozen = 0
        r.flash = 1
        local F = S.F[p.f]
        F.captured = F.captured + 1
        if old > 0 then S.F[old].lost = S.F[old].lost + 1 end
        if p.f == 1 then S.stat.cap = S.stat.cap + 1 end
        if old == 1 then S.stat.lost = S.stat.lost + 1 end
        ev(S, { k = "capture", r = r.i, f = p.f, old = old })
        SIM.recount(S)
    else
        ev(S, { k = "hit", r = r.i, f = p.f })
    end
end

-- abilities ----------------------------------------------------------------
function SIM.use(S, f, k, ri)
    local a = D.ABIL[k]
    local F = S.F[f]
    if S.over or not SIM.abil_ready(S, f, k) then return false end
    local r = ri and S.R[ri]
    if a.target and (not r or not r.active) then return false end
    if a.key == "airdrop" then
        S.fx.drops[#S.fx.drops + 1] = { f = f, r = ri, t = 1.2, n = a.n }
    elseif a.key == "march" then
        F.march_t = a.dur
    elseif a.key == "frost" then
        S.fx.frost[#S.fx.frost + 1] = { f = f, x = r.x, z = r.z, rad = a.rad, t = a.dur, dur = a.dur }
        for _, o in ipairs(S.R) do
            local dx, dz = o.x - r.x, o.z - r.z
            if o.active and o.owner ~= f and dx * dx + dz * dz < a.rad * a.rad then o.frozen = a.dur end
        end
    elseif a.key == "barrage" then
        if r.owner == f then return false end
        S.fx.shells[#S.fx.shells + 1] = { f = f, r = ri, t = 1.0 }
    end
    F.cd[k] = a.cd * F.cdmul
    ev(S, { k = "abil", a = a.key, f = f, r = ri })
    return true
end

local function update_fx(S, dt)
    local fx = S.fx
    for i = #fx.drops, 1, -1 do
        local d = fx.drops[i]
        d.t = d.t - dt
        if d.t <= 0 then
            table.remove(fx.drops, i)
            arrive(S, { f = d.f, k = d.n, dst = d.r })
            ev(S, { k = "drop", r = d.r, f = d.f })
        end
    end
    for i = #fx.frost, 1, -1 do
        local q = fx.frost[i]
        q.t = q.t - dt
        if q.t <= 0 then table.remove(fx.frost, i) end
    end
    for i = #fx.shells, 1, -1 do
        local s = fx.shells[i]
        s.t = s.t - dt
        if s.t <= 0 then
            table.remove(fx.shells, i)
            local r = S.R[s.r]
            local a = D.ABIL[D.ABIX.barrage]
            if r.owner ~= s.f then r.n = max(0, r.n - min(a.maxk, r.n * a.frac)); r.hit = S.t end
            local rr = a.rad * a.rad
            for _, p in ipairs(S.P) do
                local dx, dz = p.x - r.x, p.z - r.z
                if p.f ~= s.f and dx * dx + dz * dz < rr then p.dead = true end
            end
            ev(S, { k = "boom", r = s.r, f = s.f })
        end
    end
end

-- clashes: packets of different factions that come close annihilate one-for-one
local HC = 0.6
local function clashes(S)
    local grid = {}
    local P = S.P
    for i, p in ipairs(P) do
        if not p.dead then
            local key = floor(p.x / HC) * 8192 + floor(p.z / HC)
            local c = grid[key]; if not c then c = {}; grid[key] = c end
            c[#c + 1] = i
        end
    end
    local R2 = D.CLASH_R * D.CLASH_R
    for i, p in ipairs(P) do
        if not p.dead and p.k > 0 then
            local cx, cz = floor(p.x / HC), floor(p.z / HC)
            for ox = -1, 1 do for oz = -1, 1 do
                local c = grid[(cx + ox) * 8192 + cz + oz]
                if c then
                    for _, j in ipairs(c) do
                        local q = P[j]
                        if j ~= i and not q.dead and q.f ~= p.f and q.k > 0 and p.k > 0 then
                            local dx, dz = q.x - p.x, q.z - p.z
                            if dx * dx + dz * dz < R2 then
                                local m = min(p.k, q.k)
                                p.k, q.k = p.k - m, q.k - m
                                if p.k <= 0 then p.dead = true end
                                if q.k <= 0 then q.dead = true end
                                S.stat.clash = S.stat.clash + m
                                ev(S, { k = "clash", x = (p.x + q.x) / 2, z = (p.z + q.z) / 2, f1 = p.f, f2 = q.f, n = m })
                            end
                        end
                    end
                end
            end end
        end
    end
end

function SIM.speed(S, p)
    local F = S.F[p.f]
    local s = D.SPEED * (S.spd or 1) * F.speedmul * (F.march_t > 0 and D.ABIL[D.ABIX.march].mul or 1)
    local c = SIM.cell(S, p.x, p.z)
    p.sea = (c == 0)
    if c == 0 then if not p.port then s = s * D.SEA_SLOW end
    elseif c > 0 and S.R[c] and S.R[c].hill then s = s * D.HILL_SLOW end
    for _, q in ipairs(S.fx.frost) do
        if q.f ~= p.f then
            local dx, dz = p.x - q.x, p.z - q.z
            if dx * dx + dz * dz < q.rad * q.rad then s = s * 0.4 end
        end
    end
    return s
end

function SIM.step(S, dt)
    if S.over then return end
    S.t = S.t + dt
    -- production & decay
    for _, r in ipairs(S.R) do
        if r.flash > 0 then r.flash = max(0, r.flash - dt) end
        if r.frozen > 0 then r.frozen = r.frozen - dt end
        if r.active and r.owner > 0 then
            local F = S.F[r.owner]
            if r.n > r.cap then
                r.n = max(r.cap, r.n - max(D.DECAY, (r.n - r.cap) * 0.08) * dt)
            elseif r.frozen <= 0 then
                r.n = min(r.cap, r.n + r.prod * F.prodmul * F.rb * (1 + 0.06 * F.mines) * dt)
            end
        elseif r.active and r.owner == 0 then
            -- neutral regrowth: slower than any owned region, paused right after an attack and while frozen
            r.regen = r.n0 and r.n < r.n0 and r.frozen <= 0 and S.t - r.hit >= D.NREGEN_WAIT or false
            if r.regen then r.n = min(r.n0, r.n + D.NREGEN * dt) end
        end
    end
    for f = 1, 5 do
        local F = S.F[f]
        if F.march_t > 0 then F.march_t = F.march_t - dt end
        for k = 1, #D.ABIL do if F.cd[k] > 0 then F.cd[k] = F.cd[k] - dt end end
    end
    -- streams emit packets
    for i = #S.ST, 1, -1 do
        local s = S.ST[i]
        s.acc = s.acc + D.EMIT * dt
        while s.acc >= 1 and s.left > 0 do s.acc = s.acc - 1; emit(S, s) end
        if s.left <= 0 then table.remove(S.ST, i) end
    end
    -- move packets
    for _, p in ipairs(S.P) do
        if not p.dead then
            p.age = p.age + dt
            local dx, dz = p.tx - p.x, p.tz - p.z
            local dl = sqrt(dx * dx + dz * dz)
            local sp = SIM.speed(S, p) * dt
            if dl <= sp + 0.35 then
                p.dead = true; p.arrived = true
                arrive(S, p)
            else
                p.x, p.z = p.x + dx / dl * sp, p.z + dz / dl * sp
            end
        end
    end
    clashes(S)
    update_fx(S, dt)
    local j = 0
    local P = S.P
    for i = 1, #P do local p = P[i]; if not p.dead then j = j + 1; P[j] = p end end
    for i = #P, j + 1, -1 do P[i] = nil end
    -- AI
    if G.AI then G.AI.update(S, dt) end
    -- end conditions
    SIM.recount(S)
    if S.F[1].troops > S.stat.peak then S.stat.peak = S.F[1].troops end
    for f = 1, 5 do local F = S.F[f]; if not F.absent then F.alive = F.nreg > 0 or F.troops > 0.5 end end
    -- the battle counts as started once the board is set up: remember how many enemy factions held land at t=0
    if not S.started then
        S.started, S.foes0 = true, 0
        for f = 2, 5 do local F = S.F[f]; if not F.absent and F.nreg > 0 then S.foes0 = S.foes0 + 1 end end
    end
    -- a win needs every enemy faction at zero regions AND zero troops in transit (packets or streams),
    -- after the battle has really started (enemies existed and at least 1 s has passed)
    local foes = false
    for f = 2, 5 do local F = S.F[f]; if not F.absent and (F.nreg > 0 or F.troops > 0) then foes = true end end
    local can_win = S.started and S.foes0 > 0 and S.t >= 1
    if not S.demo then
        if not S.F[1].alive then S.over, S.win = true, false; ev(S, { k = "lose" })
        elseif not foes and can_win then
            S.over, S.win = true, true; ev(S, { k = "win" })
        end
    else
        local alive = 0
        for f = 1, 5 do if S.F[f].alive then alive = alive + 1 end end
        if alive <= 1 or S.t > 240 then S.over = true end
    end
end

-- helpers for UI / AI
function SIM.incoming(S, ri)
    local mine, foe = 0, 0
    local r = S.R[ri]
    for _, p in ipairs(S.P) do if p.dst == ri then if p.f == r.owner then mine = mine + p.k else foe = foe + p.k end end end
    for _, s in ipairs(S.ST) do if s.dst == ri then if s.f == r.owner then mine = mine + s.left else foe = foe + s.left end end end
    return mine, foe
end
function SIM.dist(S, a, b) local ra, rb = S.R[a], S.R[b]; local dx, dz = ra.x - rb.x, ra.z - rb.z; return sqrt(dx * dx + dz * dz) end
function SIM.region_at(S, x, z)
    local c = SIM.cell(S, x, z)
    if c > 0 and S.R[c] and S.R[c].active then return c end
    return nil
end
end
do -- 04b_ai.lua
------------------------------------------------------------------ 04b_ai: rival commanders with personalities
local D, SIM = G.D, G.SIM
local AI = {}
G.AI = AI
local floor, min, max, sqrt = math.floor, math.min, math.max, math.sqrt

-- troops needed to take r if they arrive after eta seconds (as seen by faction f)
local function tally(S)
    local inc = {}
    for _, p in ipairs(S.P) do local t = inc[p.dst]; if not t then t = {}; inc[p.dst] = t end; t[p.f] = (t[p.f] or 0) + p.k end
    for _, s in ipairs(S.ST) do local t = inc[s.dst]; if not t then t = {}; inc[s.dst] = t end; t[s.f] = (t[s.f] or 0) + s.left end
    S._inc = inc
    return inc
end
AI.tally = tally
local function need_for(S, f, r, eta)
    local n = r.n
    if r.owner > 0 and r.frozen <= 0 then
        local F = S.F[r.owner]
        n = min(r.cap, n + r.prod * F.prodmul * eta)
    end
    local t = (S._inc or tally(S))[r.i]
    local own_f, mine = 0, 0
    if t then own_f = t[f] or 0; if r.owner > 0 then mine = t[r.owner] or 0 end end
    return (n + mine) * SIM.def(S, r) - own_f
end
AI.need_for = need_for

local function value(S, F, P, r)
    local v = 10 + r.size * 3 + (D.TYPES[r.ty].val or 0)
    if r.owner == 1 then v = v * P.pbias elseif r.owner == 0 then v = v * P.nbias end
    if P.vult > 0 and S.t - r.hit < 6 then v = v * (1 + P.vult) end
    if r.owner > 0 and r.owner ~= F.f and S.F[r.owner].nreg <= 2 then v = v * 1.4 end -- finish off weak rivals
    return v
end

local function plan_attack(S, F, P, mine, used, reach)
    reach = (reach or P.reach) * (S.reachmul or 1)
    local best, bs, bsrc, bam
    local speed = D.SPEED * F.speedmul
    for _, r in ipairs(S.R) do
        if r.active and r.owner ~= F.f then
            -- nearest own region
            local dmin = 1e9
            for _, m in ipairs(mine) do local d = SIM.dist(S, m.i, r.i); if d < dmin then dmin = d end end
            if dmin < reach then
                local need = need_for(S, F.f, r, dmin / speed) + 2
                if need > 0 then
                    local sc = value(S, F, P, r) / (need + 1.5 * dmin)
                    if not bs or sc > bs then
                        -- gather sources (closest first) with their spare troops
                        local list = {}
                        for _, m in ipairs(mine) do
                            if not used[m.i] and m.frozen <= 0 then
                                local spare = m.n - P.keep * m.cap
                                if spare >= 3 then list[#list + 1] = { i = m.i, s = spare, d = SIM.dist(S, m.i, r.i) } end
                            end
                        end
                        table.sort(list, function(a, b) return a.d < b.d end)
                        local got, src, am = 0, {}, {}
                        for _, c in ipairs(list) do
                            if c.d < reach * 1.3 then
                                src[#src + 1] = c.i; am[#am + 1] = c.s; got = got + c.s
                                if got >= need * 1.15 + (r.owner > 0 and r.prod * (c.d - dmin) / speed or 0) then break end
                            end
                        end
                        local eta_need = need * 1.15
                        if got >= eta_need then
                            -- trim the excess from the last source so the garrisons are not stripped bare
                            local over = got - eta_need - 2
                            if over > 0 then am[#am] = max(1, am[#am] - over) end
                            best, bs, bsrc, bam = r, sc, src, am
                        end
                    end
                end
            end
        end
    end
    return best, bsrc, bam
end

local function defend(S, F, P, mine, used)
    for _, m in ipairs(mine) do
        local _, foe = SIM.incoming(S, m.i)
        if foe > m.n * SIM.def(S, m) * 0.9 then
            local short = foe / SIM.def(S, m) - m.n + 3
            local src, am, got = {}, {}, 0
            for _, o in ipairs(mine) do
                if o.i ~= m.i and not used[o.i] and o.frozen <= 0 and SIM.dist(S, o.i, m.i) < 9 then
                    local spare = o.n - 0.25 * o.cap
                    if spare >= 3 then src[#src + 1] = o.i; am[#am + 1] = min(spare, short - got); got = got + am[#am] end
                end
                if got >= short then break end
            end
            if got >= short * 0.6 and #src > 0 then
                SIM.send(S, F.f, src, m.i, nil, am)
                for _, i in ipairs(src) do used[i] = true end
                return true
            end
        end
    end
    return false
end

local function abilities(S, F, P, mine)
    if not P.abil then return end
    -- frost the player's strongest cluster
    local k = D.ABIX.frost
    if SIM.abil_ready(S, F.f, k) then
        local best, bv
        for _, r in ipairs(S.R) do
            if r.active and r.owner > 0 and r.owner ~= F.f then
                local v = 0
                for _, o in ipairs(S.R) do if o.owner == r.owner and SIM.dist(S, r.i, o.i) < 5 then v = v + o.n end end
                if r.owner == 1 then v = v * 1.2 end
                if not bv or v > bv then best, bv = r, v end
            end
        end
        if best and bv > 40 then SIM.use(S, F.f, k, best.i) end
    end
    k = D.ABIX.barrage
    if SIM.abil_ready(S, F.f, k) then
        local best, bv
        for _, r in ipairs(S.R) do
            if r.active and r.owner ~= F.f and r.owner > 0 and r.n > 15 then
                local v = r.n * (r.owner == 1 and 1.3 or 1)
                if not bv or v > bv then best, bv = r, v end
            end
        end
        if best then SIM.use(S, F.f, k, best.i) end
    end
    k = D.ABIX.airdrop
    if SIM.abil_ready(S, F.f, k) then
        -- reinforce a threatened region, else grab the weakest reachable target
        local tgt
        for _, m in ipairs(mine) do local _, foe = SIM.incoming(S, m.i); if foe > m.n then tgt = m.i end end
        if not tgt then
            local bv
            for _, r in ipairs(S.R) do
                if r.active and r.owner ~= F.f and r.n * SIM.def(S, r) < 10 then
                    if not bv or r.n < bv then tgt, bv = r.i, r.n end
                end
            end
        end
        if tgt then SIM.use(S, F.f, k, tgt) end
    end
    k = D.ABIX.march
    if SIM.abil_ready(S, F.f, k) then
        local fly = 0
        for _, p in ipairs(S.P) do if p.f == F.f then fly = fly + p.k end end
        if fly > 30 then SIM.use(S, F.f, k) end
    end
end

function AI.think(S, F)
    local P = D.PERS[F.ai]
    local mine = {}
    for _, r in ipairs(S.R) do if r.active and r.owner == F.f then mine[#mine + 1] = r end end
    if #mine == 0 then return end
    local used = {}
    tally(S)
    defend(S, F, P, mine, used)
    -- every garrison near its cap: the front is stalled, so mass troops from further away (ocean crossings)
    local sn, sc = 0, 0
    for _, m in ipairs(mine) do sn = sn + m.n; sc = sc + m.cap end
    local rr = (sn > 0.85 * sc and #mine >= 6) and 40 or nil
    for _ = 1, P.acts do
        local r, src, am = plan_attack(S, F, P, mine, used, rr)
        -- nothing in reach for a while (rival hiding on an island / far corner): widen the search
        if not r and S.t - (F.last_act or 0) > 10 then r, src, am = plan_attack(S, F, P, mine, used, 99) end
        if not r then break end
        F.last_act = S.t
        SIM.send(S, F.f, src, r.i, nil, am)
        for _, i in ipairs(src) do used[i] = true end
        tally(S)
    end
    abilities(S, F, P, mine)
    S._inc = nil
end

function AI.update(S, dt)
    if S.t < S.ai_delay then return end
    for f = 1, 5 do
        local F = S.F[f]
        if F.ai and F.alive and (f ~= 1 or S.demo) then
            F.think = F.think - dt
            if F.think <= 0 then
                local P = D.PERS[F.ai]
                F.think = P.iv * (F.ivm or 1) * (0.85 + 0.3 * math.random())
                AI.think(S, F)
            end
        end
    end
end
end
------------------------------------------------------------------ 05_render: the living board (tiles, flags, marching figures, rings, arrows, ability props)
do
local RN = { evi = 0, sndt = {} }
G.RN = RN
local MAXFIG = 260
local KINDS = { "ring_sel", "ring_tgt", "chev", "dot", "dot_bad", "dot_rim", "ice", "shell", "crate" }
for f = 0, 5 do KINDS[#KINDS + 1] = "flag_" .. f end
for f = 1, 5 do KINDS[#KINDS + 1] = "sol_" .. f; KINDS[#KINDS + 1] = "ber_" .. f; KINDS[#KINDS + 1] = "boat_" .. f end
RN.KINDS = KINDS

function RN.reset(S)
    RN.flag = {}
    RN.col = {}
    RN.sndt = {}
    RN.fy = {}
    for i, r in ipairs(S.R) do RN.flag[i] = { owner = r.owner, t = 1 } end
end

local function snd(name, gap)
    local t = RN.sndt[name] or -9
    if G.t - t < (gap or 0.08) then return end
    RN.sndt[name] = G.t
    sfx(name)
end
RN.snd = snd

-- ground height under a world point
local function ground(S, x, z)
    local c = G.SIM.cell(S, x, z)
    if c > 0 then local r = S.R[c]; return r and r.h or 0.5, false end
    if c == 0 then return 0.02, true end
    return 0.3, false
end
RN.ground = ground

local function tiles(S, sel, hov, dt)
    for i, r in ipairs(S.R) do
        local T = G.BD.tiles[i]
        if T then
            local p
            if not r.active then p = { 0.62, 0.6, 0.56 } else p = G.D.FAC[r.owner].pastel end
            local c = RN.col[i]
            if not c then c = { p[1], p[2], p[3] }; RN.col[i] = c end
            local k = 1 - math.exp(-6 * dt)
            for j = 1, 3 do c[j] = c[j] + (p[j] - c[j]) * k end
            local em = 0
            if sel[i] then em = 0.28 + 0.08 * math.sin(G.t * 6) elseif hov == i then em = 0.16 end
            em = em + r.flash * 0.6
            local fr = r.frozen > 0 and 1 or 0
            local b = { c[1] * (1 - 0.35 * fr) + 0.35 * fr * 0.8, c[2] * (1 - 0.35 * fr) + 0.35 * fr * 0.92, c[3] * (1 - 0.35 * fr) + 0.35 * fr * 1.0 }
            local key = string.format("%.3f%.3f%.3f|%.2f", b[1], b[2], b[3], em)
            T.age = (T.age or 0) + 1
            if T.age <= 10 then T.key = nil end   -- build_board's deferred material replays (frames 2 and 6) would otherwise wipe the starting owners' tint
            if T.key ~= key then
                T.key = key
                G.tint_tile(i, b, { b[1] * em, b[2] * em, b[3] * em })
            end
        end
    end
end

local function flags(S, dt)
    for f = 0, 5 do P_begin("flag_" .. f) end
    for i, r in ipairs(S.R) do
        if r.active then
            local fl = RN.flag[i]
            if fl.owner ~= r.owner then fl.owner = r.owner; fl.t = 0 end
            fl.t = min(1, fl.t + dt * 1.6)
            local e = 1 - (1 - fl.t) ^ 3
            local n = P_get("flag_" .. r.owner)
            local s = r.ty == "capital" and 0.55 or 0.45
            place(n, r.x - 0.45, r.h + (e - 1) * 0.9 * s, r.z + 0.45, s, s * (0.4 + 0.6 * e), s, 180 + math.sin(G.t * 1.3 + i) * 8)
        end
    end
    for f = 0, 5 do P_end("flag_" .. f) end
end

local function figures(S, dt)
    for f = 1, 5 do P_begin("sol_" .. f); P_begin("ber_" .. f); P_begin("boat_" .. f) end
    local P = S.P
    local step = max(1, math.ceil(#P / MAXFIG))
    local fy = RN.fy
    local seen = {}
    for idx = 1, #P, step do
        local p = P[idx]
        local h, sea = ground(S, p.x, p.z)
        local y = fy[p.id] or h
        y = y + (h - y) * min(1, dt * 10)
        fy[p.id] = y; seen[p.id] = true
        local kind = (sea and not p.port and "boat_" or (sea and "boat_" or (p.bearer and "ber_" or "sol_"))) .. p.f
        local n = P_get(kind)
        local dx, dz = p.tx - p.x, p.tz - p.z
        local ry = math.deg(math.atan2(dx, dz))
        local s = 0.36 * (1 + 0.14 * min(p.k - 1, 5)) * (sea and 1.15 or 1)
        local bob = sea and (math.sin(G.t * 3 + p.id) * 0.03) or (abs(math.sin(G.t * 9 + p.id * 1.7)) * 0.06)
        local sway = sea and math.sin(G.t * 2 + p.id) * 4 or math.sin(G.t * 9 + p.id * 1.7) * 5
        local pop = min(1, p.age * 5)
        place(n, p.x, y + bob, p.z, s * pop, s * pop, s * pop, ry, 0, sway)
    end
    for id in pairs(fy) do if not seen[id] then fy[id] = nil end end
    for f = 1, 5 do P_end("sol_" .. f); P_end("ber_" .. f); P_end("boat_" .. f) end
end

-- rings under selected / targeted regions; a line of big round dots from each selected region to the target
-- (white core on an Azure rim; grey on a dark rim while the cursor has no valid target). Dots are opaque meshes
-- lifted 0.16 above the ground under them, with a gentle pulse travelling toward the target.
local DOT_SP, DOT_LIFT, DOT_MAX, DOT_K = 1.1, 0.16, 120, 1.9   -- spacing, lift, pool budget, dot size
local function dot_line(S, r, tx, tz, ok, budget)
    local dx, dz = tx - r.x, tz - r.z
    local dl = math.sqrt(dx * dx + dz * dz)
    if dl < 1.6 then return 0 end
    local ux, uz = dx / dl, dz / dl
    local d0, d1 = 1.05, dl - (ok and 1.2 or 0.3)
    local n = math.max(0, math.floor((d1 - d0) / DOT_SP + 0.5))
    local sp = n > 0 and (d1 - d0) / n or 0
    local kind = ok and "dot" or "dot_bad"
    local cnt = 0
    for k = 0, n do
        if cnt >= budget then break end
        local d = d0 + k * sp
        local x, z = r.x + ux * d, r.z + uz * d
        local h = ground(S, x, z)
        local w = math.cos(d * 1.2 - G.t * 7.5)
        local s = DOT_K * (1 + (ok and 0.28 or 0.1) * (w > 0 and w * w * w * w or 0))
        place(P_get("dot_rim"), x, h + DOT_LIFT, z, s, 1, s, 0)
        place(P_get(kind), x, h + DOT_LIFT + 0.02, z, s, s, s, 0)
        cnt = cnt + 1
    end
    return cnt
end
RN.dot_line = dot_line

local function rings(S, sel, tgt, drag)
    P_begin("ring_sel"); P_begin("ring_tgt"); P_begin("chev"); P_begin("dot"); P_begin("dot_bad"); P_begin("dot_rim")
    for i in pairs(sel) do
        local r = S.R[i]
        local s = 0.7 + 0.15 * r.size
        place(P_get("ring_sel"), r.x, r.h + 0.04, r.z, s, 1, s, G.t * 40)
    end
    if tgt then
        local r = S.R[tgt]
        local s = (0.8 + 0.15 * r.size) * (1 + 0.06 * math.sin(G.t * 8))
        place(P_get("ring_tgt"), r.x, r.h + 0.05, r.z, s, 1, s, -G.t * 50)
    end
    -- send preview: while dragging, or while hovering a target with regions selected
    if drag or tgt then
        local cnt = 0
        for i in pairs(sel) do
            if i ~= tgt then
                local r = S.R[i]
                local tx, tz, ok
                if tgt then tx, tz, ok = S.R[tgt].x, S.R[tgt].z, true else tx, tz, ok = drag.x, drag.z, false end
                cnt = cnt + dot_line(S, r, tx, tz, ok, DOT_MAX - cnt)
            end
        end
    end
    P_end("ring_sel"); P_end("ring_tgt"); P_end("chev"); P_end("dot"); P_end("dot_bad"); P_end("dot_rim")
end

local function props(S)
    P_begin("ice"); P_begin("shell"); P_begin("crate")
    for i, r in ipairs(S.R) do
        if r.active and r.frozen > 0 then
            local k = min(1, r.frozen * 2)
            place(P_get("ice"), r.x + 0.5, r.h, r.z - 0.35, 0.55 * k, 0.6 * k, 0.55 * k, i * 40)
        end
    end
    for _, s in ipairs(S.fx.shells) do
        local r = S.R[s.r]
        local k = 1 - s.t
        place(P_get("shell"), r.x + (1 - k) * 2.5, r.h + 9 * (1 - k) + 0.3, r.z - (1 - k) * 3, 1.3, 1.3, 1.3, 0, 30 + 40 * k)
    end
    for _, d in ipairs(S.fx.drops) do
        local r = S.R[d.r]
        local k = 1 - d.t / 1.2
        place(P_get("crate"), r.x + 0.4, r.h + 8 * (1 - k) + 0.3, r.z + 0.2, 0.7, 0.7, 0.7, G.t * 30, math.sin(G.t * 4) * 6)
    end
    P_end("ice"); P_end("shell"); P_end("crate")
end

-- one-shot effects + sounds from sim events
local function events(S)
    local FX, D = G.FX, G.D
    for _, e in ipairs(S.ev) do
        if e.k == "capture" then
            local r = S.R[e.r]
            local col = D.FAC[e.f].col
            FX.capture(r.x, r.h, r.z, col)
            if e.f == 1 then snd("capture", 0.15) elseif e.old == 1 then snd("lost", 0.15); if G.HUD and not S.demo then G.HUD.toast(r.name .. " lost!", "red", nil, "lost" .. e.r) end
            else snd("neutral", 0.2) end
            if G.on_capture then G.on_capture(S, e) end
        elseif e.k == "hit" then
            if math.random() < 0.25 then local r = S.R[e.r]; FX.hit(r.x, r.h, r.z, D.FAC[e.f].col) end
        elseif e.k == "clash" then
            local h = ground(S, e.x, e.z)
            if math.random() < 0.5 then FX.clash(e.x, h, e.z, e.n) end
            snd("clash", 0.12)
        elseif e.k == "send" then
            if e.f == 1 then snd("send", 0.15) end
        elseif e.k == "drop" then
            local r = S.R[e.r]; FX.airdrop(r.x, r.h, r.z, D.FAC[e.f].col); snd("airdrop", 0.1)
        elseif e.k == "boom" then
            local r = S.R[e.r]; FX.barrage(r.x, r.h, r.z); snd("boom", 0.1)
        elseif e.k == "abil" then
            if e.a == "frost" then local r = S.R[e.r]; FX.frost(r.x, r.h, r.z, D.ABIL[D.ABIX.frost].rad); snd("frost", 0.1)
            elseif e.a == "march" then snd("march_horn", 0.1)
            elseif e.a == "barrage" then snd("whistle", 0.1) end
            if e.f ~= 1 and G.HUD and not S.demo then G.HUD.toast(D.FAC[e.f].short .. " used " .. D.ABIL[D.ABIX[e.a]].name .. "!", "orange", nil, "ab" .. e.a) end
        end
    end
    S.ev = {}
end

function RN.update(S, dt, sel, hov, tgt, drag)
    events(S)
    tiles(S, sel, hov, dt)
    flags(S, dt)
    figures(S, dt)
    rings(S, sel, tgt, drag)
    props(S)
end
function RN.clear()
    for _, k in ipairs(KINDS) do P_begin(k); P_end(k) end
end
end
------------------------------------------------------------------ UI kit: runtime_ui quads, one mouse backdrop, keyboard focus
local UI = { name = "bb" }
G.UI = UI
do
local NAME = UI.name
runtime_ui.show(NAME); pcall(runtime_ui.set_screen_overlay, NAME, true)
local US = SH / 1080
UI.US = US
local CLEAR = { 0, 0, 0, 0 }
local cache, last, used, shown = {}, {}, {}, {}
local function Q(id, o)
    used[id] = true
    o.visible = true
    if o.style == nil then o.style = "text" end
    if o.fill == nil then o.fill = CLEAR end
    if o.border == nil then o.border = CLEAR end
    if o.no_input == nil then o.no_input = true end
    local f, tc, b = o.fill, o.text_color or CLEAR, o.border
    local key = string.format("%.1f|%.1f|%.1f|%.1f|%s|%.2f|%.3f%.3f%.3f%.3f|%.3f%.3f%.3f%.3f|%.2f%.2f%.2f%.2f|%s|%s|", o.x, o.y, o.w, o.h, o.label or "",
        o.font_scale or 1, f[1], f[2], f[3], f[4], tc[1], tc[2], tc[3], tc[4], b[1], b[2], b[3], b[4], tostring(o.z), (o.align_h or "") .. (o.image or "") .. (o.image_tint and string.format("%.2f", o.image_tint[4]) or ""))
    if cache[id] == key then return end
    cache[id] = key; last[id] = o
    pcall(runtime_ui.set_quad, NAME, id, o)
end
UI.Q = Q
function UI.begin_frame() used = {} end
function UI.end_frame()
    for id in pairs(shown) do
        if not used[id] and last[id] then local o = last[id]; o.visible = false; pcall(runtime_ui.set_quad, NAME, id, o); cache[id] = nil end
    end
    shown = used
end
-- shapes
function UI.rect(id, x, y, w, h, fill, r, z, border)
    Q(id, { x = x, y = y, w = w, h = h, z = z or 5, label = "", fill = fill, border = border, corner_radius = (r or 0) * US })
end
function UI.text(id, label, x, y, w, h, fs, col, align, z, shadow)
    if shadow ~= false then
        Q(id .. "~", { x = x + 3 * US, y = y + 4 * US, w = w, h = h, z = (z or 10) - 0.5, label = label, text_color = { 0.05, 0.08, 0.2, (col and col[4] or 1) * 0.45 },
            font_scale = fs * US, align_h = align or "center", align_v = "middle" })
    end
    Q(id, { x = x, y = y, w = w, h = h, z = z or 10, label = label, text_color = col or { 1, 1, 1, 1 }, font_scale = fs * US, align_h = align or "center", align_v = "middle" })
end
-- outlined big text (four dark copies around) - the chunky mobile look for counters and gate values
function UI.big(id, label, cx, cy, fs, col, out, z)
    local w, h = 900 * US, fs * 26 * US
    local x, y = cx - w / 2, cy - h / 2
    local o = (out or 3) * US
    local oc = { 0.06, 0.1, 0.25, (col and col[4] or 1) * 0.85 }
    local k = 0
    for _, d in ipairs({ { -1, 0 }, { 1, 0 }, { 0, -1 }, { 0, 1 }, { 0.8, 1.6 } }) do
        k = k + 1
        Q(id .. "~" .. k, { x = x + d[1] * o, y = y + d[2] * o, w = w, h = h, z = (z or 10) - 0.5, label = label, text_color = oc, font_scale = fs * US, align_h = "center", align_v = "middle" })
    end
    Q(id, { x = x, y = y, w = w, h = h, z = z or 10, label = label, text_color = col or { 1, 1, 1, 1 }, font_scale = fs * US, align_h = "center", align_v = "middle" })
end
-- palettes for buttons {top, lip, text}
local BTN = {
    green = { { .30, .80, .32, 1 }, { .15, .52, .2, 1 } }, blue = { { .25, .58, 1, 1 }, { .12, .34, .75, 1 } },
    orange = { { 1, .62, .16, 1 }, { .78, .38, .06, 1 } }, red = { { .95, .32, .3, 1 }, { .66, .14, .14, 1 } },
    purple = { { .6, .4, 1, 1 }, { .38, .22, .74, 1 } }, white = { { .97, .97, 1, 1 }, { .72, .76, .86, 1 } },
    grey = { { .62, .65, .72, 1 }, { .42, .45, .52, 1 } }, gold = { { 1, .8, .25, 1 }, { .8, .55, .1, 1 } },
}
UI.BTN = BTN
-- mouse via one transparent backdrop (all visuals are no_input) + keyboard focus over this frame's buttons
local MS = { x = -1, y = -1, down = false, prev = false, click = false, got = false, release = false }
UI.MS = MS
local list, focus, fscreen = {}, 1, nil
UI.list = list
function UI.poll(screen)
    if screen ~= fscreen then fscreen = screen; focus = 1; UI.kbd = false end
    Q("backdrop", { x = 0, y = 0, w = SW, h = SH, z = 900, label = "", no_input = false, bring_to_front = true })
    local ok, s = pcall(runtime_ui.get_state, NAME, "backdrop")
    local down = false
    local clicked = false
    if ok and type(s) == "table" then
        if s.mouse_x then MS.moved = abs((s.mouse_x or 0) - MS.x) + abs((s.mouse_y or 0) - MS.y) > 2; MS.x, MS.y = s.mouse_x, s.mouse_y end
        down = s.down and true or false
        clicked = s.clicked and true or false
    end
    poll_mouse()
    if G.vmouse then MS.moved = abs(MOUSE.x - MS.x) + abs(MOUSE.y - MS.y) > 2; MS.x, MS.y = MOUSE.x, MOUSE.y; down = G.vmouse.down or false; clicked = G.vmouse.click or false; G.vmouse.click = false end
    if not down and MOUSE.down and not G.vmouse then down = true end
    MS.click = false
    if down and not MS.prev then MS.click = true; MS.got = true; MS.px, MS.py = MS.x, MS.y end
    if clicked and not MS.got then MS.click = true; MS.px, MS.py = MS.x, MS.y end
    MS.release = (not down and MS.prev) or (clicked and not MS.prev)
    if not down then MS.got = false end
    MS.prev = down; MS.down = down
    -- keys
    local K = {}
    K.up = anyedge("Up", "W"); K.down = anyedge("Down", "S"); K.left = anyedge("Left", "A"); K.right = anyedge("Right", "D")
    K.ok = anyedge("Return", "Space"); K.back = anyedge("Escape")
    UI.K = K
    -- focus moves on this frame using last frame's button list
    local n = #list
    if n > 0 then
        if K.down or K.right then focus = focus % n + 1; UI.kbd = true; sfx("hover") end
        if K.up or K.left then focus = (focus - 2) % n + 1; UI.kbd = true; sfx("hover") end
    end
    UI.prev_list = list
    UI.activate = (K.ok and n > 0) and list[focus] or nil
    list = {}
    UI.list = list
end
local function inside(x, y, w, h) return MS.x >= x and MS.x <= x + w and MS.y >= y and MS.y <= y + h end
UI.inside = inside
-- rough label width in em (DejaVu-like proportions) so button text can be fitted to one line
local NARROW = { i = .3, l = .3, j = .3, t = .42, f = .38, r = .44, I = .32, [" "] = .34, ["."] = .34, [","] = .34, [":"] = .36, ["!"] = .4, ["'"] = .3, ["|"] = .34 }
local function em_width(label)
    local w = 0
    for ch in tostring(label):gmatch(".") do
        local c = NARROW[ch]
        if not c then
            if ch:match("[MW]") then c = .98 elseif ch:match("[mw]") then c = .9 elseif ch:match("%u") then c = .74
            elseif ch:match("%d") then c = .64 else c = .6 end
        end
        w = w + c
    end
    return w
end
UI.em_width = em_width
UI.EM = 12.6           -- reference-pixel em per font_scale unit (calibrated against box screenshots)
-- font tiers so every button of the same rank reads the same: hero (title Campaign), main (dialog buttons), small (inline)
UI.FS = { hero = 3.6, main = 2.7, small = 2.3 }
UI.GAP = 28            -- minimum gap between neighbouring buttons in 1080p reference pixels (scales with US)
-- largest font_scale <= fs that keeps label on one line inside a w x h (reference px) button with side padding
function UI.fit_fs(label, fs, w, h)
    local pad = math.max(22, h * 0.28)
    local ew = em_width(label)
    if ew > 0 then fs = math.min(fs, (w - 2 * pad) / (ew * UI.EM)) end
    return math.min(fs, h / 27)
end
-- button: returns true when clicked (mouse) or activated (keyboard focus + Enter/Space)
function UI.button(id, label, cx, cy, w, h, kind, opt)
    opt = opt or {}
    w, h = w * US, h * US
    local x, y = cx - w / 2, cy - h / 2
    local idx = -1
    if not opt.nokbd then idx = #list + 1; list[idx] = id end
    local hov = inside(x, y, w, h)
    if hov and MS.moved and idx > 0 then focus = idx; UI.kbd = false end
    local foc = (focus == idx) or (opt.nokbd and hov)
    local pal = BTN[opt.disabled and "grey" or (kind or "blue")]
    local press = (hov and MS.down) and 4 * US or 0
    local grow = (foc and not opt.disabled) and 1.025 or 1
    local gw, gh = w * grow, h * grow
    local gx, gy = cx - gw / 2, cy - gh / 2
    local lip = 7 * US
    local r = opt.r or min(h / US / 2, 26)
    if foc then UI.rect(id .. "_f", gx - 4 * US, gy - 4 * US + press, gw + 8 * US, gh + lip + 8 * US, { 1, 1, 1, 0.95 }, r + 4, (opt.z or 20) - 1) end
    UI.rect(id .. "_l", gx, gy + lip, gw, gh, pal[2], r, (opt.z or 20))
    UI.rect(id .. "_t", gx, gy + press, gw, gh, pal[1], r, (opt.z or 20) + 0.1)
    UI.rect(id .. "_h", gx + 8 * US, gy + press + 5 * US, gw - 16 * US, gh * 0.38, { 1, 1, 1, foc and 0.28 or 0.18 }, r * 0.7, (opt.z or 20) + 0.2)
    if label ~= "" then
        local tc = (kind == "white") and { .15, .22, .4, 1 } or { 1, 1, 1, 1 }
        UI.text(id .. "_x", label, gx, gy + press + (opt.ty or 0) * US, gw, gh, UI.fit_fs(label, opt.fs or UI.FS.main, w / US, h / US) * grow, tc, "center", (opt.z or 20) + 0.3, kind ~= "white")
    end
    if opt.disabled then return false end
    local hit = (MS.click and inside(x, y, w, h)) or UI.activate == id
    if hit then sfx("click") end
    return hit
end
function UI.focus_index() return focus end
function UI.set_focus(i) focus = i end
-- panel card with a soft drop shadow
function UI.card(id, x, y, w, h, fill, z)
    UI.rect(id .. "_s", x + 6 * US, y + 10 * US, w, h, { 0.05, 0.1, 0.25, 0.25 }, 30, (z or 5) - 0.2)
    UI.rect(id, x, y, w, h, fill or { .98, .98, 1, 0.97 }, 30, z or 5)
end
-- icons are generated PNGs (tools/gen_ui.py)
function UI.img(id, name, cx, cy, size, z, tint)
    local s = size * US
    Q(id, { style = "image", image = "Textures/ui/" .. name .. ".png", image_tint = tint or { 1, 1, 1, 1 }, x = cx - s / 2, y = cy - s / 2, w = s, h = s, z = z or 12, label = "" })
end
function UI.coin_icon(id, cx, cy, s, z) UI.img(id, "coin", cx, cy, s, z) end
function UI.gem_icon(id, cx, cy, s, z) UI.img(id, "medal", cx, cy, s, z) end
function UI.star(id, cx, cy, s, on, z) UI.img(id, on and "star" or "star_off", cx, cy, s, z) end
-- currency pill
function UI.pill(id, x, y, w, icon, value, z)
    local h = 58 * US
    UI.rect(id, x, y, w * US, h, { .08, .14, .32, 0.55 }, 29, z or 30)
    if icon == "coin" then UI.coin_icon(id .. "i", x + 30 * US, y + h / 2, 40, (z or 30) + 1) else UI.gem_icon(id .. "i", x + 30 * US, y + h / 2, 36, (z or 30) + 1) end
    UI.text(id .. "v", value, x + 60 * US, y, w * US - 66 * US, h, 1.9, { 1, 1, 1, 1 }, "left", (z or 30) + 1)
end
end
------------------------------------------------------------------ 07_hud: region badges, top strength bar, ability tray, tooltips, toasts + menu screens
do
local U, D, SIM = G.UI, G.D, G.SIM
local US = U.US
local HUD = { toasts = {}, zones = {} }
G.HUD = HUD
local function fmt(n)
    n = floor((n or 0) + 0.5)
    local s = tostring(abs(n))
    local o = s:reverse():gsub("(%d%d%d)", "%1,"):reverse()
    if o:sub(1, 1) == "," then o = o:sub(2) end
    return (n < 0 and "-" or "") .. o
end
HUD.fmt = fmt
local function mmss(t) t = floor(t or 0); return string.format("%d:%02d", floor(t / 60), t % 60) end
HUD.mmss = mmss
local TCOL = { gold = { 1, .78, .2, 1 }, orange = { 1, .58, .18, 1 }, blue = { .35, .7, 1, 1 }, red = { 1, .35, .3, 1 }, grey = { .8, .84, .9, 1 }, green = { .4, .95, .45, 1 } }
local WHITE = { 1, 1, 1, 1 }
local INK = { .24, .16, .08, 1 }
local PARCH = { .98, .94, .84, .97 }
local WOOD = { .23, .15, .09, .92 }
HUD.INK, HUD.PARCH, HUD.WOOD = INK, PARCH, WOOD
local function fc(f, a) local c = D.FAC[f].col; return { c[1], c[2], c[3], a or 1 } end
local function sh(c, k, a) return { c[1] * k, c[2] * k, c[3] * k, a or c[4] or 1 } end
HUD.fc = fc

function HUD.reset() HUD.toasts, HUD.ban, HUD.hnt = {}, nil, nil end
function HUD.toast(txt, col, icon, key)
    for _, t in ipairs(HUD.toasts) do if t.txt == txt or (key and t.key == key) then t.txt = txt; t.t = math.min(t.t, 0.2); return end end
    table.insert(HUD.toasts, 1, { txt = txt, col = TCOL[col] or TCOL.gold, icon = icon, t = 0, key = key })
    if #HUD.toasts > 3 then HUD.toasts[4] = nil end
end
function HUD.banner(a, b, col) HUD.ban = { a = a, b = b, t = 0, col = col } end
function HUD.hint(txt) HUD.hnt = { txt = txt, t = 0 } end

-- screen zones the HUD owns this frame (map clicks inside them are ignored)
local function zone(x, y, w, h) HUD.zones[#HUD.zones + 1] = { x, y, w, h } end
function HUD.over()
    for _, z in ipairs(HUD.zones) do if U.inside(z[1], z[2], z[3], z[4]) then return true end end
    return false
end

-- floating troop badges over every region
-- ocean / neighbour captions printed on the sea (tools/gen_maps.py sea_labels), e.g. New Zealand's Tasman Sea and the way to Australia
local function sea_labels(S)
    local sea = S.M and S.M.sea
    if not sea then return end
    for k, q in ipairs(sea) do
        local sx, sy, zc = project(q.x, 0.05, q.z)
        if zc > 0.3 and sx > -300 and sx < SW + 300 and sy > -40 and sy < SH + 40 then
            local fs = clamp(70 / zc, 1.5, 2.6) * q.k
            U.text("sea" .. k, q.t, sx - 300 * US, sy - 24 * US, 600 * US, 48 * US, fs, { .86, .95, 1, .62 }, "center", 4, true)
        end
    end
end
function HUD.badges(S, sel, hov, tgt, focus)
    sea_labels(S)
    for i, r in ipairs(S.R) do
        if r.active then
            local sx, sy, zc = project(r.x, r.h + 0.55, r.z)
            if zc > 0.3 and sx > -80 and sx < SW + 80 and sy > -60 and sy < SH + 60 then
                local s = clamp(30 / zc, 0.62, 1.25)
                local hitk = clamp(1 - (S.t - r.hit) / 0.25, 0, 1)
                sx = sx + math.sin(G.t * 60) * 3 * US * hitk
                local pop = 1 + r.flash * 0.35
                s = s * pop
                local n = floor(r.n)
                local txt = tostring(n)
                local w, h = (30 + 14 * #txt) * s * US, 38 * s * US
                local col = fc(r.owner)
                if r.owner == 0 then col = { .52, .49, .44, 1 } end
                local ring = sel[i] and { 1, 1, 1, 1 } or ((tgt == i or focus == i) and { 1, .84, .3, 1 } or sh(col, 0.45, 0.95))
                local bw = (sel[i] or tgt == i or focus == i) and 4 * US or 2.5 * US
                U.rect("bo" .. i, sx - w / 2 - bw, sy - h / 2 - bw, w + 2 * bw, h + 2 * bw, ring, h / US / 2 + 3, 6)
                U.rect("bb" .. i, sx - w / 2, sy - h / 2, w, h, col, h / US / 2, 6.1)
                U.rect("bh" .. i, sx - w / 2 + 4 * US, sy - h / 2 + 3 * US, w - 8 * US, h * 0.4, { 1, 1, 1, .2 }, h / US / 3, 6.15)
                if r.frozen > 0 then U.rect("bf" .. i, sx - w / 2, sy - h / 2, w, h, { .75, .92, 1, .55 }, h / US / 2, 6.2) end
                U.text("bt" .. i, txt, sx - w / 2, sy - h / 2, w, h, 1.6 * s, WHITE, "center", 6.3)
                -- fill gauge (troops vs cap) under the pill
                if r.owner > 0 then
                    local k = clamp(r.n / r.cap, 0, 1)
                    local gw = w * 0.8
                    U.rect("bg" .. i, sx - gw / 2, sy + h / 2 + 3 * US, gw, 5 * US * s, { .1, .07, .04, .55 }, 3, 6)
                    U.rect("bk" .. i, sx - gw / 2, sy + h / 2 + 3 * US, max(2, gw * k), 5 * US * s, k >= 0.99 and { 1, .85, .3, 1 } or { 1, 1, 1, .9 }, 3, 6.05)
                end
                -- neutral regrowth gauge (garrison vs starting garrison): green while regrowing, grey while paused after a hit
                if r.owner == 0 and r.n0 and r.n < r.n0 - 0.01 then
                    local k = clamp(r.n / r.n0, 0, 1)
                    local gw = w * 0.8
                    U.rect("bg" .. i, sx - gw / 2, sy + h / 2 + 3 * US, gw, 5 * US * s, { .1, .07, .04, .55 }, 3, 6)
                    U.rect("bk" .. i, sx - gw / 2, sy + h / 2 + 3 * US, max(2, gw * k), 5 * US * s, r.regen and { .45, .95, .5, 1 } or { .8, .78, .74, .9 }, 3, 6.05)
                end
                if r.ty ~= "town" then U.img("bi" .. i, "t_" .. r.ty, sx - w / 2 - 12 * s * US, sy - 2 * US, 34 * s, 6.4) end
            end
        end
    end
end

-- tooltip for the hovered region
function HUD.tip(S, i)
    local r = S.R[i]
    if not r then return end
    local x, y, w, h = 24 * US, SH - 236 * US, 430 * US, 212 * US
    U.card("tp", x, y, w, h, PARCH, 40)
    local own = D.FAC[r.owner]
    U.rect("tpb", x, y, w, 52 * US, r.owner == 0 and { .55, .52, .46, 1 } or fc(r.owner), 30, 40.1)
    U.text("tpn", r.name, x + 18 * US, y, w - 36 * US, 52 * US, 1.8, WHITE, "left", 40.3)
    U.text("tpo", own.short or own.name, x + 18 * US, y, w - 36 * US, 52 * US, 1.3, { 1, 1, 1, .9 }, "right", 40.3, false)
    local tl = D.TYPE_DESC[r.ty] or "Town"
    if r.hill then tl = tl .. "  ·  Hills: troops march 20% slower" end
    U.text("tpd", tl, x + 18 * US, y + 58 * US, w - 36 * US, 56 * US, 1.12, { .4, .3, .2, 1 }, "left", 40.3, false)
    local rate = r.owner > 0 and r.prod * S.F[r.owner].prodmul * S.F[r.owner].rb * (1 + 0.06 * S.F[r.owner].mines) or 0
    U.text("tp1", "Troops", x + 18 * US, y + 112 * US, 200 * US, 40 * US, 1.35, { .45, .35, .25, 1 }, "left", 40.3, false)
    U.text("tp1v", floor(r.n) .. " / " .. floor(r.owner == 0 and (r.n0 or r.n) or r.cap), x + 200 * US, y + 112 * US, w - 218 * US, 40 * US, 1.5, INK, "right", 40.3, false)
    U.text("tp2", "Recruits", x + 18 * US, y + 148 * US, 200 * US, 40 * US, 1.35, { .45, .35, .25, 1 }, "left", 40.3, false)
    U.text("tp2v", r.owner > 0 and string.format("+%.1f / s", rate) or ((r.n0 and r.n < r.n0 - 0.01) and (r.regen and string.format("+%.2f / s", D.NREGEN) or "paused") or "-"), x + 200 * US, y + 148 * US, w - 218 * US, 40 * US, 1.5, INK, "right", 40.3, false)
    U.text("tp3", string.format("Defence x%.1f", SIM.def(S, r)), x + 18 * US, y + 176 * US, w - 36 * US, 34 * US, 1.15, { .45, .35, .25, 1 }, "left", 40.3, false)
end

-- top bar: level, clock, faction strength
function HUD.top(S, demo)
    local act
    local bw = 820 * US
    local x0 = SW / 2 - bw / 2
    local y0 = 18 * US
    local tot = 0
    local list = {}
    for f = 1, 5 do local F = S.F[f]; if not F.absent then local v = max(0, F.troops) + F.nreg * 4; if F.alive then tot = tot + v; list[#list + 1] = { f = f, v = v, F = F } end end end
    U.rect("sb_bg", x0 - 8 * US, y0 - 6 * US, bw + 16 * US, 50 * US, WOOD, 20, 30)
    local x = x0
    for j, e in ipairs(list) do
        local w = tot > 0 and bw * e.v / tot or bw / #list
        if j == #list then w = x0 + bw - x end
        U.rect("sb" .. e.f, x, y0, w, 38 * US, fc(e.f), 14, 30.2)
        U.rect("sbh" .. e.f, x, y0, w, 14 * US, { 1, 1, 1, .18 }, 8, 30.3)
        if w > 90 * US then U.text("sbt" .. e.f, (D.FAC[e.f].short) .. "  " .. e.F.nreg, x, y0, w, 38 * US, 1.25, WHITE, "center", 30.4) end
        x = x + w
    end
    zone(x0 - 8 * US, 0, bw + 16 * US, 70 * US)
    if not demo then
        U.rect("lv_bg", 18 * US, 14 * US, 380 * US, 58 * US, WOOD, 22, 30)
        U.text("lv_t", S.li .. ".  " .. S.L.name, 34 * US, 14 * US, 260 * US, 58 * US, 1.45, { 1, .9, .7, 1 }, "left", 30.2)
        U.text("lv_c", mmss(S.t), 250 * US, 14 * US, 132 * US, 58 * US, 1.6, WHITE, "right", 30.2)
        zone(18 * US, 14 * US, 380 * US, 58 * US)
        if U.button("pz", "II", SW - 64 * US, 44 * US, 76, 64, "white", { nokbd = true, fs = 2.4 }) then act = "pause" end
        zone(SW - 110 * US, 0, 110 * US, 90 * US)
    end
    return act
end

-- bottom tray: 4 abilities + send ratio
function HUD.tray(S, pick, ratio)
    local act
    local n = #D.ABIL
    local sz = 104 * US
    local gap = 18 * US
    local total = n * sz + (n - 1) * gap + 150 * US
    local x0 = SW / 2 - total / 2
    local y0 = SH - sz - 26 * US
    U.rect("tr_bg", x0 - 16 * US, y0 - 12 * US, total + 32 * US, sz + 30 * US, WOOD, 26, 30)
    zone(x0 - 16 * US, y0 - 12 * US, total + 32 * US, sz + 40 * US)
    for k, a in ipairs(D.ABIL) do
        local x = x0 + (k - 1) * (sz + gap)
        local id = "ab" .. k
        local unl = SIM.abil_unlocked(S, k)
        local fr = clamp(SIM.abil_frac(S, 1, k), 0, 1)
        local ready = unl and SIM.abil_ready(S, 1, k)
        local on = pick == k
        local hov = U.inside(x, y0, sz, sz)
        local bc = on and { 1, .85, .3, 1 } or (ready and { .95, .8, .45, .5 + .5 * abs(math.sin(G.t * 3)) } or { .1, .07, .04, 1 })
        U.rect(id .. "o", x - 4 * US, y0 - 4 * US, sz + 8 * US, sz + 8 * US, bc, 22, 30.4)
        U.rect(id .. "b", x, y0, sz, sz, hov and { .46, .34, .22, 1 } or { .36, .26, .16, 1 }, 18, 30.5)
        if unl then
            U.img(id .. "i", a.icon, x + sz / 2, y0 + sz / 2 - 6 * US, 74, 30.7, ready and WHITE or { .6, .6, .6, 1 })
            if not ready then
                local hh = sz * (1 - fr)
                U.rect(id .. "c", x, y0, sz, hh, { .05, .03, .02, .6 }, 18, 30.8)
                local cd = S.F[1].cd[k]
                if cd > 0 then U.text(id .. "t", tostring(math.ceil(cd)), x, y0, sz, sz - 14 * US, 2.4, WHITE, "center", 30.9) end
            end
            U.text(id .. "n", a.name, x - 10 * US, y0 + sz - 26 * US, sz + 20 * US, 26 * US, 0.95, { 1, .95, .85, 1 }, "center", 30.9)
        else
            U.img(id .. "l", "lock", x + sz / 2, y0 + sz / 2 - 8 * US, 46, 30.7, { 1, 1, 1, .7 })
            U.text(id .. "n", "Level " .. a.unlock, x, y0 + sz - 28 * US, sz, 26 * US, 1.0, { 1, .9, .7, .8 }, "center", 30.9)
        end
        U.text(id .. "k", tostring(k), x + 6 * US, y0 + 2 * US, 26 * US, 28 * US, 1.2, { 1, .85, .4, 1 }, "center", 30.95)
        if hov then
            U.card("abtp", x + sz / 2 - 220 * US, y0 - 108 * US, 440 * US, 84 * US, PARCH, 41)
            U.text("abtpn", a.name .. (unl and "" or "  (locked)"), x + sz / 2 - 210 * US, y0 - 106 * US, 420 * US, 38 * US, 1.4, INK, "center", 41.2, false)
            U.text("abtpd", a.desc, x + sz / 2 - 210 * US, y0 - 70 * US, 420 * US, 38 * US, 1.1, { .45, .35, .25, 1 }, "center", 41.2, false)
        end
        if U.MS.click and hov then act = k end
    end
    -- ratio toggle
    local rx = x0 + n * (sz + gap) + 4 * US
    local rhov = U.inside(rx, y0, 130 * US, sz)
    U.rect("ra_o", rx - 4 * US, y0 - 4 * US, 138 * US, sz + 8 * US, { .1, .07, .04, 1 }, 22, 30.4)
    U.rect("ra_b", rx, y0, 130 * US, sz, rhov and { .46, .34, .22, 1 } or { .36, .26, .16, 1 }, 18, 30.5)
    U.text("ra_l", "Send", rx, y0 + 6 * US, 130 * US, 30 * US, 1.1, { 1, .9, .7, .9 }, "center", 30.7)
    U.text("ra_v", ratio >= 1 and "100%" or "50%", rx, y0 + 30 * US, 130 * US, 50 * US, 2.3, ratio >= 1 and WHITE or { 1, .85, .4, 1 }, "center", 30.7)
    U.text("ra_k", "Space", rx, y0 + sz - 28 * US, 130 * US, 26 * US, 0.95, { 1, .9, .7, .7 }, "center", 30.7)
    if U.MS.click and rhov then act = "ratio" end
    return act
end
function HUD.begin() HUD.zones = {} end

-- tutorial card (top centre, under the strength bar)
function HUD.tut(step, i, n)
    if not step then return end
    local w, h = 900 * US, 92 * US
    local x, y = SW / 2 - w / 2, 92 * US
    local bob = math.sin(G.t * 3) * 3 * US
    U.card("tu", x, y + bob, w, h, PARCH, 35)
    U.rect("tub", x, y + bob, 110 * US, h, { .25, .56, .94, 1 }, 30, 35.1)
    U.text("tun", i .. "/" .. n, x, y + bob, 110 * US, h, 2.0, WHITE, "center", 35.3)
    U.text("tut", step.txt, x + 126 * US, y + bob, w - 146 * US, h, 1.35, INK, "left", 35.3, false)
    zone(x, y, w, h)
end

-- targeting hint for an ability
function HUD.pick_hint(k)
    local a = D.ABIL[k]
    local txt = a.name .. ": click a region  ·  Right-click / Esc cancels"
    local w = (#txt * 15 + 80) * US
    U.rect("pk_bg", SW / 2 - w / 2, SH - 200 * US, w, 52 * US, { .9, .6, .15, .9 }, 26, 34)
    U.text("pk_t", txt, SW / 2 - w / 2, SH - 200 * US, w, 52 * US, 1.45, WHITE, "center", 34.2)
end

-- overlays drawn in every state (toasts, banner, hint)
function HUD.overlays(dt)
    -- while a dialog is open (pause / options / win / lose) the battle banner, toasts and hints stay hidden
    local st = G.state
    local modal = st == "pause" or st == "options" or st == "win" or st == "lose"
    for i = #HUD.toasts, 1, -1 do
        local t = HUD.toasts[i]
        t.t = t.t + dt
        if t.t > 2.4 then table.remove(HUD.toasts, i) end
    end
    for i, t in ipairs(modal and {} or HUD.toasts) do
        local a = clamp(min(t.t * 6, (2.4 - t.t) * 3), 0, 1)
        local y = 220 * US + (i - 1) * 60 * US
        local s = 1 + max(0, 0.15 - t.t) * 2
        local w = (#t.txt * 19 + 70) * US
        U.rect("to" .. i, SW - w - 30 * US, y - 24 * US, w, 50 * US, { t.col[1] * .55, t.col[2] * .55, t.col[3] * .55, .85 * a }, 25, 44)
        U.text("tt" .. i, t.txt, SW - w - 30 * US, y - 24 * US, w, 50 * US, 1.6 * s, { 1, 1, 1, a }, "center", 45)
    end
    local b = HUD.ban
    if b then
        b.t = b.t + dt
        if b.t > 3.0 or modal then HUD.ban = nil
        else
            local a = clamp(min(b.t * 4, (3.0 - b.t) * 3), 0, 1)
            local s = 1 + max(0, 0.25 - b.t) * 2
            local c = b.col or { .2, .14, .08 }
            U.rect("ban_bg", 0, SH * 0.34, SW, 170 * US, { c[1], c[2], c[3], .7 * a }, 0, 44)
            U.big("ban_b", b.b or "", SW / 2, SH * 0.34 + 45 * US, 2.2, { 1, .9, .75, a }, 2, 45)
            U.big("ban_a", b.a, SW / 2, SH * 0.34 + 112 * US, 4.8 * s, { 1, 1, 1, a }, 4, 45)
        end
    end
    local h = HUD.hnt
    if h then
        h.t = h.t + dt
        if h.t > 4 or modal then HUD.hnt = nil
        else
            local a = clamp(min(h.t * 4, (4 - h.t) * 2), 0, 1)
            local w = (#h.txt * 16 + 70) * US
            U.rect("hn_bg", SW / 2 - w / 2, SH - 270 * US, w, 54 * US, { .1, .07, .04, .7 * a }, 27, 44)
            U.text("hn_t", h.txt, SW / 2 - w / 2, SH - 270 * US, w, 54 * US, 1.5, { 1, 1, 1, a }, "center", 45)
        end
    end
end

